import{_ as r,a8 as l,o as i,c as d,ah as n,K as o}from"./chunks/framework.B6ehkn__.js";import"./chunks/theme.BfMjDZ3-.js";const N=JSON.parse('{"title":"NLP-基础概念","description":"","frontmatter":{"title":"NLP-基础概念","abstract":"自然语言处理基础概念，涵盖 NLP 的定义、从规则驱动、统计方法到深度学习的发展简史及各阶段代表技术与里程碑。","created":"2026-05-23T00:00:00.000Z","tags":["NLP","基础概念"],"type":"概念解释","related":[],"category":["🤖 AI大模型","NLP基础"]},"headers":[],"relativePath":"vault/Knowledge/AI/NLP-基础概念.md","filePath":"vault/Knowledge/AI/NLP-基础概念.md","lastUpdated":1790655645000}'),s={name:"vault/Knowledge/AI/NLP-基础概念.md"};function p(h,t,u,c,g,_){const a=l("NolebaseGitContributors"),e=l("NolebaseGitChangelog");return i(),d("div",null,[t[0]||(t[0]=n('<h3 id="什么是自然语言处理" tabindex="-1">什么是自然语言处理 <a class="header-anchor" href="#什么是自然语言处理" aria-label="Permalink to “什么是自然语言处理”">​</a></h3><p>自然语言处理（Natural Language Processing, 简称NLP）是计算机科学与语言学中关注于计算机与人类语言间转换的领域，是人工智能与语言学的交叉学科</p><blockquote><p>NLP 就是让计算机理解人类的语言</p></blockquote><hr><h3 id="发展简史" tabindex="-1">发展简史 <a class="header-anchor" href="#发展简史" aria-label="Permalink to “发展简史”">​</a></h3><h5 id="按技术范式划分" tabindex="-1">按技术范式划分 <a class="header-anchor" href="#按技术范式划分" aria-label="Permalink to “按技术范式划分”">​</a></h5><ol><li><p>规则驱动时期（1950s-1980s）</p><ul><li><p><strong>1950年</strong>：艾伦·图灵提出&quot;图灵测试&quot;，奠定NLP理论基础</p></li><li><p><strong>1954年</strong>：乔治城-IBM实验首次实现俄英机器翻译（60余句），但过度乐观的预期导致1966年ALPAC报告后经费大幅削减</p></li><li><p><strong>1960年代</strong>：代表性系统</p><ul><li><strong>SHRDLU</strong>：受限&quot;积木世界&quot;中的对话系统</li><li><strong>ELIZA</strong>：模拟心理治疗的聊天机器人，暴露早期模式匹配的局限性</li></ul></li><li><p>特点：依赖语言学专家手工编写规则，系统脆弱、泛化能力差</p></li></ul></li><li><p>统计方法兴起（1980s-2010s）</p><ul><li><p><strong>关键转折</strong>：摩尔定律提升算力 + 乔姆斯基形式语言学式微 → 机器学习成为主流</p></li><li><p><strong>技术突破</strong>：</p><ul><li>隐马尔可夫模型（HMM）用于词性标注</li><li>统计机器翻译（IBM主导），利用双语语料库训练概率模型</li><li>条件随机场（CRF, 2001）成为序列标注标准方法</li></ul></li><li><p>特点：从&quot;人工规则&quot;转向&quot;数据驱动&quot;，系统鲁棒性显著提升</p></li></ul></li><li><p>深度学习时代（2011年至今）</p><table tabindex="0"><thead><tr><th>年份</th><th>里程碑</th><th>意义</th></tr></thead><tbody><tr><td>2013</td><td>Word2Vec提出</td><td>实现高效词嵌入，开启分布式表示时代<br></td></tr><tr><td>2014</td><td>Seq2Seq框架</td><td>统一机器翻译、文本生成等序列建模任务</td></tr><tr><td>2015</td><td>Attention机制</td><td>解决长序列依赖，提升模型可解释性</td></tr><tr><td>2017</td><td>Transformer架构</td><td>并行计算+自注意力，奠定大模型基础</td></tr><tr><td>2018</td><td>BERT预训练</td><td>&quot;预训练+微调&quot;范式成为NLP新标准</td></tr><tr><td>2022+</td><td>大语言模型（LLM）</td><td>ChatGPT等推动NLP从&quot;理解&quot;转向&quot;生成&quot;<br></td></tr></tbody></table></li></ol><h5 id="按历史阶段划分" tabindex="-1">按历史阶段划分 <a class="header-anchor" href="#按历史阶段划分" aria-label="Permalink to “按历史阶段划分”">​</a></h5><ol><li><strong>萌芽期（1956年前）</strong> ：图灵测试、机器翻译构想提出</li><li><strong>快速发展期（1957-1970）</strong> ：达特茅斯会议（1956）标志AI诞生，符号主义与统计方法并行探索</li><li><strong>低谷期（1971-1993）</strong> ：规则方法瓶颈显现，&quot;人工智能寒冬&quot;影响研究投入</li><li><strong>复苏融合期（1994至今）</strong> ：互联网爆发+算力提升+大数据积累，推动NLP与深度学习、大模型深度融合</li></ol><hr><h3 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to “应用场景”">​</a></h3><ul><li>语音助手</li><li>机器翻译</li><li>搜素引擎</li><li>智能问答</li></ul><p>‍</p>',13)),o(a),o(e)])}const L=r(s,[["render",p]]);export{N as __pageData,L as default};
